def calc(expr: str) -> int:
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif expr[i] in '+-*/()':
            tokens.append(expr[i])
            i += 1
        else:
            i += 1

    class Parser:
        def __init__(self, tokens):
            self.tokens = tokens
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def consume(self):
            token = self.peek()
            self.pos += 1
            return token

        def parse_expr(self):
            left = self.parse_term()
            while self.peek() in ('+', '-'):
                op = self.consume()
                right = self.parse_term()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            return left

        def parse_term(self):
            left = self.parse_unary()
            while self.peek() in ('*', '/'):
                op = self.consume()
                right = self.parse_unary()
                if op == '*':
                    left = left * right
                else:
                    # Integer division truncating toward zero
                    if (left < 0) != (right < 0):
                        left = -(abs(left) // abs(right))
                    else:
                        left = abs(left) // abs(right)
            return left

        def parse_unary(self):
            unary_ops = 0
            while self.peek() in ('+', '-'):
                op = self.consume()
                if op == '-':
                    unary_ops += 1

            value = self.parse_primary()

            if unary_ops % 2 == 1:
                value = -value

            return value

        def parse_primary(self):
            token = self.peek()
            if token == '(':
                self.consume()
                result = self.parse_expr()
                self.consume()  # consume ')'
                return result
            elif isinstance(token, int):
                self.consume()
                return token
            else:
                return 0

    parser = Parser(tokens)
    return parser.parse_expr()

